ALTER TABLE public.payment_policies ADD COLUMN frequency text NOT NULL DEFAULT 'ONCE' CHECK(frequency IN ('ONCE','DAILY','WEEKLY','MONTHLY')), ADD COLUMN execution_date date, ADD COLUMN auto_approve_limit numeric(14,2) CHECK(auto_approve_limit>=0 AND auto_approve_limit<=100000), ADD COLUMN retry_delay_seconds integer NOT NULL DEFAULT 5 CHECK(retry_delay_seconds IN (5,900,3600));
UPDATE public.payment_policies SET max_retries=2 WHERE max_retries>2;
ALTER TABLE public.payment_policies DROP CONSTRAINT payment_policies_max_retries_check;
ALTER TABLE public.payment_policies ADD CONSTRAINT payment_policies_max_retries_check CHECK(max_retries BETWEEN 0 AND 2);
ALTER TABLE public.sync_requests ADD COLUMN next_execution_at timestamptz, ADD COLUMN retry_attempts integer NOT NULL DEFAULT 0 CHECK(retry_attempts BETWEEN 0 AND 2);
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,title text NOT NULL,message text NOT NULL,type text NOT NULL CHECK(type IN ('COLLECTION','APPROVAL','TRANSFER','FAILURE','RETRY')),related_id uuid REFERENCES public.simulation_transfers(id),is_read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.notifications TO authenticated;
GRANT UPDATE(is_read) ON public.notifications TO authenticated;
GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_owner_read ON public.notifications FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()));
CREATE POLICY notification_owner_mark ON public.notifications FOR UPDATE TO authenticated USING(user_id=(SELECT auth.uid())) WITH CHECK(user_id=(SELECT auth.uid()));
CREATE TRIGGER notifications_updated BEFORE UPDATE ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE INDEX notifications_owner_unread ON public.notifications(user_id,is_read,created_at DESC);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications; END IF; END $$;
CREATE FUNCTION public.lookup_wallet_recipient(p_query text) RETURNS TABLE(user_id uuid,name text,alias text,email text) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; RETURN QUERY SELECT w.user_id,p.name,CASE WHEN w.email=lower(trim(p_query)) THEN w.email WHEN w.upi_id=lower(trim(p_query)) THEN w.upi_id ELSE w.phone END,w.email FROM public.simulation_wallets w JOIN public.profiles p ON p.id=w.user_id WHERE w.discoverable AND w.user_id<>auth.uid() AND ((w.email=lower(trim(p_query)) AND w.email<>'') OR (w.upi_id=lower(trim(p_query)) AND w.upi_id<>'') OR (w.phone=trim(p_query) AND w.phone<>'')) LIMIT 2; END $$;
REVOKE ALL ON FUNCTION public.lookup_wallet_recipient(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.lookup_wallet_recipient(text) TO authenticated;
CREATE FUNCTION payiq_private.notify_transfer() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE target uuid; kind text; heading text; BEGIN
IF TG_OP='INSERT' THEN target:=NEW.payer_id; kind:=CASE WHEN NEW.requester_id<>NEW.payer_id THEN 'COLLECTION' ELSE 'APPROVAL' END; heading:=CASE WHEN kind='COLLECTION' THEN 'Incoming Smart Transfer' ELSE 'Awaiting Approval' END;
ELSIF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('SUCCESS','FAILED') THEN target:=NEW.recipient_id; kind:=CASE WHEN NEW.status='SUCCESS' THEN 'TRANSFER' ELSE 'FAILURE' END; heading:=CASE WHEN NEW.status='SUCCESS' THEN 'Transfer received' ELSE 'Smart Transfer failed' END;
ELSE RETURN NEW; END IF;
INSERT INTO public.notifications(user_id,title,message,type,related_id) VALUES(target,heading,'Amount: ₹'||NEW.amount||CASE WHEN kind IN ('COLLECTION','APPROVAL') THEN ' · Awaiting your approval' ELSE ' · '||NEW.status END,kind,NEW.id);
IF kind='FAILURE' THEN INSERT INTO public.notifications(user_id,title,message,type,related_id) VALUES(NEW.payer_id,heading,'Amount: ₹'||NEW.amount,kind,NEW.id); END IF;
IF NEW.status IN ('SUCCESS','FAILED','CANCELLED') THEN UPDATE public.notifications SET is_read=true WHERE related_id=NEW.id AND type IN ('COLLECTION','APPROVAL'); END IF;
RETURN NEW; END $$;
REVOKE ALL ON FUNCTION payiq_private.notify_transfer() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER transfer_notifications AFTER INSERT OR UPDATE ON public.simulation_transfers FOR EACH ROW EXECUTE FUNCTION payiq_private.notify_transfer();
CREATE FUNCTION public.execute_smart_transfer(p_sync uuid,p_amount numeric DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE s public.sync_requests; pol public.payment_policies; person uuid; result uuid; amt numeric; existing public.simulation_transfers; due timestamptz; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
SELECT * INTO s FROM public.sync_requests WHERE id=p_sync AND user_id=auth.uid() FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Smart Transfer not found'; END IF;
SELECT * INTO pol FROM public.payment_policies WHERE id=s.policy_id AND user_id=auth.uid();
IF NOT FOUND THEN RAISE EXCEPTION 'Policy not found'; END IF;
IF pol.execution_date IS NOT NULL AND pol.execution_date>current_date AND s.last_at IS NULL THEN UPDATE public.sync_requests SET next_execution_at=pol.execution_date::timestamptz WHERE id=s.id; RETURN NULL; END IF;
IF s.next_execution_at IS NOT NULL AND s.next_execution_at>now() THEN RETURN NULL; END IF;
SELECT * INTO existing FROM public.simulation_transfers WHERE sync_request_id=s.id AND status IN ('AWAITING_USER_AUTH','SUCCESS') ORDER BY created_at DESC LIMIT 1;
IF FOUND THEN RETURN existing.id; END IF;
IF s.retry_attempts>=pol.max_retries AND s.status='FAILED' THEN RAISE EXCEPTION 'Retry limit reached'; END IF;
amt:=coalesce(p_amount,s.amount);
IF amt IS NULL THEN RAISE EXCEPTION 'Review and enter an exact amount'; END IF;
SELECT r.user_id INTO person FROM public.lookup_wallet_recipient(s.counterparty_address) r;
IF person IS NULL AND s.counterparty_email<>'' THEN SELECT r.user_id INTO person FROM public.lookup_wallet_recipient(s.counterparty_email) r; END IF;
IF person IS NULL THEN RAISE EXCEPTION 'Registered recipient not found or lookup disabled'; END IF;
IF s.status='FAILED' THEN UPDATE public.sync_requests SET retry_attempts=retry_attempts+1 WHERE id=s.id;
INSERT INTO public.notifications(user_id,title,message,type) VALUES(person,'Smart Transfer retry','Retry '||(s.retry_attempts+1)||' of '||pol.max_retries||' · ₹'||amt,'RETRY'); END IF;
result:=payiq_private.prepare_simulation_transfer(person,amt,s.id);
IF s.direction='DEBIT' AND NOT pol.requires_user_auth AND (pol.auto_approve_limit IS NULL OR amt<=pol.auto_approve_limit) THEN
PERFORM payiq_private.confirm_simulation_transfer(result);
ELSE UPDATE public.sync_requests SET status='AWAITING_USER_AUTH',next_execution_at=NULL WHERE id=s.id;
END IF;
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.execute_smart_transfer(uuid,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.execute_smart_transfer(uuid,numeric) TO authenticated;
CREATE FUNCTION payiq_private.transfer_schedule() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE pol public.payment_policies; attempts integer; BEGIN IF NEW.sync_request_id IS NULL OR NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
SELECT p.* INTO pol FROM public.payment_policies p JOIN public.sync_requests s ON s.policy_id=p.id WHERE s.id=NEW.sync_request_id;
SELECT retry_attempts INTO attempts FROM public.sync_requests WHERE id=NEW.sync_request_id;
IF NEW.status='FAILED' THEN UPDATE public.sync_requests SET next_execution_at=CASE WHEN attempts<pol.max_retries THEN now()+make_interval(secs=>pol.retry_delay_seconds) ELSE NULL END WHERE id=NEW.sync_request_id;
ELSIF NEW.status='SUCCESS' THEN UPDATE public.sync_requests SET retry_attempts=0,next_execution_at=CASE pol.frequency WHEN 'DAILY' THEN now()+interval '1 day' WHEN 'WEEKLY' THEN now()+interval '1 week' WHEN 'MONTHLY' THEN now()+interval '1 month' ELSE NULL END WHERE id=NEW.sync_request_id;
END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION payiq_private.transfer_schedule() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER transfer_schedule AFTER UPDATE ON public.simulation_transfers FOR EACH ROW EXECUTE FUNCTION payiq_private.transfer_schedule();